begin;
select plan(51);
-- Actual pinned Google AAL1, no auth overrides and no reauthentication evidence.
select set_config('test.completion_amr',floor(extract(epoch from clock_timestamp()-interval '2 minutes'))::text,true);
insert into auth.users(id,aud,role,email,email_confirmed_at,created_at,updated_at) values('d1100000-0000-4000-8000-000000000001','authenticated','authenticated','manager@care.example.invalid',now(),now(),now());
insert into auth.identities(id,provider_id,user_id,identity_data,provider) values(gen_random_uuid(),'completion-manager','d1100000-0000-4000-8000-000000000001','{"sub":"completion-manager","email":"manager@care.example.invalid","email_verified":true}','google');
insert into auth.sessions(id,user_id,created_at,aal) values('d1200000-0000-4000-8000-000000000001','d1100000-0000-4000-8000-000000000001',now()-interval '3 minutes','aal1');
insert into auth.mfa_amr_claims(id,session_id,created_at,updated_at,authentication_method) values(gen_random_uuid(),'d1200000-0000-4000-8000-000000000001',to_timestamp(current_setting('test.completion_amr')::bigint),to_timestamp(current_setting('test.completion_amr')::bigint),'oauth');
insert into public.organizations(id,code,name) values('d1300000-0000-4000-8000-000000000001','completion-test','合成機構');
insert into public.branches(id,organization_id,code,name) values
 ('d1400000-0000-4000-8000-000000000001','d1300000-0000-4000-8000-000000000001','main','合成分支'),
 ('d1400000-0000-4000-8000-000000000002','d1300000-0000-4000-8000-000000000001','other','另一分支');
insert into public.profiles(id,display_name,kind) values('d1100000-0000-4000-8000-000000000001','合成主管','staff');
insert into public.memberships(id,organization_id,branch_id,profile_id,status,starts_at) values('d1500000-0000-4000-8000-000000000001','d1300000-0000-4000-8000-000000000001','d1400000-0000-4000-8000-000000000001','d1100000-0000-4000-8000-000000000001','active',now()-interval '1 year');
insert into public.membership_roles(membership_id,role_id) values('d1500000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000003');
insert into public.clients(id,organization_id,branch_id,client_code,display_name) values
 ('d1600000-0000-4000-8000-000000000001','d1300000-0000-4000-8000-000000000001','d1400000-0000-4000-8000-000000000001','C-1','合成待收案'),
 ('d1600000-0000-4000-8000-000000000002','d1300000-0000-4000-8000-000000000001','d1400000-0000-4000-8000-000000000001','C-2','合成待收案二'),
 ('d1600000-0000-4000-8000-000000000003','d1300000-0000-4000-8000-000000000001','d1400000-0000-4000-8000-000000000002','C-3','跨分支個案');
insert into private.staff_google_access_grants(allowed_user_id,organization_id,company_email_domain,allowed_email,google_subject,enabled,approval_reference)
values('d1100000-0000-4000-8000-000000000001','d1300000-0000-4000-8000-000000000001','care.example.invalid','manager@care.example.invalid','completion-manager',true,'Synthetic completion approval');
select set_config('request.jwt.claims',jsonb_build_object('sub','d1100000-0000-4000-8000-000000000001','session_id','d1200000-0000-4000-8000-000000000001','role','authenticated','aud','authenticated','aal','aal1','is_anonymous',false,'email','manager@care.example.invalid','iat',floor(extract(epoch from now())),'exp',floor(extract(epoch from now()+interval '30 minutes')),'amr',jsonb_build_array(jsonb_build_object('method','oauth','timestamp',current_setting('test.completion_amr')::bigint)))::text,true);
create function pg_temp.admit(p_kind public.client_transition_kind default 'admit',p_client uuid default 'd1600000-0000-4000-8000-000000000001',p_key uuid default 'd1700000-0000-4000-8000-000000000001',p_version bigint default 1) returns jsonb language sql as $$
 select to_jsonb(t) from public.transition_client('d1300000-0000-4000-8000-000000000001','d1400000-0000-4000-8000-000000000001',p_client,p_kind,(now() at time zone 'Asia/Taipei')::date,'已確認評估、文件及服務日',null,p_version,p_key)t;$$;
create function pg_temp.roster(p_override jsonb default '{}') returns jsonb language sql as $$
 select receipt from public.save_care_roster('d1300000-0000-4000-8000-000000000001','d1400000-0000-4000-8000-000000000001',jsonb_build_object('clientId','d1600000-0000-4000-8000-000000000001','staffUserId',null,'serviceDate',(now() at time zone 'Asia/Taipei')::date,'shift','morning','expectedVersion',0,'state','scheduled','sourceNote','已核對照顧計畫','tasks',jsonb_build_array('temperature'),'approved',true,'idempotency_key','d1800000-0000-4000-8000-000000000001')||p_override);$$;
create function pg_temp.access(p_action text,p_client uuid default null) returns boolean language sql as $$
 select public.has_routine_completion_access('d1300000-0000-4000-8000-000000000001','d1400000-0000-4000-8000-000000000001',p_action,p_client);$$;
select ok(not has_function_privilege('anon','public.has_routine_completion_access(uuid,uuid,text,uuid)','execute'),'anonymous cannot preflight');
select ok(not has_function_privilege('service_role','public.has_routine_completion_access(uuid,uuid,text,uuid)','execute'),'service key cannot impersonate routine staff');
select ok(not has_table_privilege('authenticated','public.client_transitions','insert,update,delete'),'no direct ledger write');
set local role authenticated;
select is(public.has_recent_aal2(15),false,'Google remains AAL1');
select is(pg_temp.access('admission.create'),true,'approved manager can admit');
select is(pg_temp.access('roster.manage'),true,'approved supervisor can allocate');
select is(pg_temp.access('death'),false,'unsupported terminal action denied');
select is(pg_temp.access('care_records.sign'),false,'no clinical signing extension');
select is(pg_temp.access('admission.create','d1600000-0000-4000-8000-000000000003'),false,'cross branch client denied');
select throws_ok($$select pg_temp.roster()$$,'23514',null,'pending admission cannot receive service roster');
select is(pg_temp.admit()->>'replayed','false','explicit formal admission completes using Google AAL1');
select is(pg_temp.admit()->>'replayed','true','admission replay stays singular');
select is((select count(*)::integer from public.client_transitions),1,'routine scoped lifecycle history visible');
select is((select count(*)::integer from public.client_directory_snapshot('d1300000-0000-4000-8000-000000000001','d1400000-0000-4000-8000-000000000001','client_lifecycle')),2,'lifecycle directory reads only selected branch');
select is(pg_temp.roster()->>'replayed','false','supervisor can allocate after admission');
select is(pg_temp.roster()->>'replayed','true','roster replay stays singular');
select is((select payload->>'manager' from public.care_roster_snapshot('d1300000-0000-4000-8000-000000000001','d1400000-0000-4000-8000-000000000001',(now() at time zone 'Asia/Taipei')::date)),'true','supervisor composer is available from real snapshot');
select throws_ok($$select pg_temp.admit('close')$$,'42501',null,'closure still needs AAL2');
select throws_ok($$select pg_temp.admit('death')$$,'42501',null,'death still needs AAL2');
select throws_ok($$select pg_temp.admit('transfer')$$,'42501',null,'transfer still needs AAL2');
select throws_ok($$select pg_temp.admit('suspend')$$,'42501',null,'suspension still needs AAL2');
select throws_ok($$select pg_temp.admit('resume')$$,'42501',null,'resumption still needs AAL2');
select throws_ok($$select pg_temp.admit('admit','d1600000-0000-4000-8000-000000000002','d1700000-0000-4000-8000-000000000002',9)$$,'40001',null,'optimistic client version is preserved');
select throws_ok($$select pg_temp.roster('{"sourceNote":"不同內容"}')$$,'23505',null,'roster idempotency body cannot change');
select throws_ok($$select pg_temp.roster('{"staffUserId":"d1100000-0000-4000-8000-000000000099","expectedVersion":1,"idempotency_key":"d1800000-0000-4000-8000-000000000002"}')$$,'42501',null,'cannot assign a person without existing client authority');
select is(public.has_routine_completion_access(gen_random_uuid(),'d1400000-0000-4000-8000-000000000001','admission.create',null),false,'a different organization cannot borrow this branch');
reset role;
create temporary table completion_permission_fixture as select * from public.role_permissions where role_id='10000000-0000-4000-8000-000000000003';
delete from public.role_permissions where role_id='10000000-0000-4000-8000-000000000003' and permission_id in(select id from public.permissions where permission_key='clients.manage');
set local role authenticated;
select throws_ok($$select pg_temp.admit()$$,'42501',null,'removing clients.manage blocks admission receipt');
select is(pg_temp.access('roster.manage'),true,'roster policy is independent of client management');
reset role;
insert into public.role_permissions select * from completion_permission_fixture on conflict do nothing;
delete from public.role_permissions where role_id='10000000-0000-4000-8000-000000000003' and permission_id in(select id from public.permissions where permission_key='staff_scheduling.manage');
set local role authenticated;
select throws_ok($$select pg_temp.roster()$$,'42501',null,'removing scheduling management blocks roster receipt');
select is(pg_temp.access('admission.create'),true,'admission policy does not grant scheduling management');
reset role;
insert into public.role_permissions select * from completion_permission_fixture on conflict do nothing;
delete from public.role_permissions where role_id='10000000-0000-4000-8000-000000000003' and permission_id in(select id from public.permissions where permission_key='clients.view_all');
set local role authenticated;
select is(pg_temp.access('admission.create','d1600000-0000-4000-8000-000000000002'),false,'client management alone cannot cross assigned-client scope');
select throws_ok($$select pg_temp.roster()$$,'42501',null,'roster requires explicit branch-wide client scope');
reset role;
insert into public.client_assignments(organization_id,branch_id,client_id,assignee_user_id,assignment_kind,starts_at) values('d1300000-0000-4000-8000-000000000001','d1400000-0000-4000-8000-000000000001','d1600000-0000-4000-8000-000000000002','d1100000-0000-4000-8000-000000000001','synthetic_admission',now()-interval '1 day');
set local role authenticated;
select is(pg_temp.access('admission.create','d1600000-0000-4000-8000-000000000002'),true,'explicit live assignment permits admission of that client only');
select is(pg_temp.access('admission.create','d1600000-0000-4000-8000-000000000001'),false,'assignment does not permit a different client');
reset role;
insert into public.role_permissions select * from completion_permission_fixture on conflict do nothing;
select set_config('test.completion_claims',current_setting('request.jwt.claims'),true);
select set_config('request.jwt.claims',jsonb_set(current_setting('request.jwt.claims')::jsonb,'{amr}',jsonb_build_array(jsonb_build_object('method','password','timestamp',current_setting('test.completion_amr')::bigint)))::text,true);
set local role authenticated;
select throws_ok($$select pg_temp.admit()$$,'42501',null,'linked Google identity cannot authorize a password session');
select throws_ok($$select pg_temp.roster()$$,'42501',null,'password session cannot allocate roster');
reset role;
select set_config('request.jwt.claims',current_setting('test.completion_claims'),true);
select is((select auth_context->>'assuranceLevel' from public.client_transitions limit 1),'aal1','admission ledger records real AAL1');
select is((select auth_context->>'assuranceLevel' from private.care_roster_versions limit 1),'aal1','roster ledger records real AAL1');
select is((select count(*)::integer from private.reauth_events),0,'no fabricated recent authentication');
update public.organizations set is_active=false where id='d1300000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select pg_temp.admit()$$,'42501',null,'disabled organization blocks admission replay');
select throws_ok($$select pg_temp.roster()$$,'42501',null,'disabled organization blocks roster replay');
reset role;
update public.organizations set is_active=true where id='d1300000-0000-4000-8000-000000000001';
update public.branches set is_active=false where id='d1400000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select pg_temp.admit()$$,'42501',null,'disabled branch blocks admission replay');
select throws_ok($$select pg_temp.roster()$$,'42501',null,'disabled branch blocks roster replay');
reset role;
update public.branches set is_active=true where id='d1400000-0000-4000-8000-000000000001';
update private.staff_google_access_grants set enabled=false;
set local role authenticated;
select throws_ok($$select pg_temp.admit()$$,'42501',null,'revoked Google grant blocks admission replay');
select throws_ok($$select pg_temp.roster()$$,'42501',null,'revoked Google grant blocks roster replay');
reset role;
update private.staff_google_access_grants set enabled=true;
update public.memberships set status='suspended' where id='d1500000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select pg_temp.admit()$$,'42501',null,'revoked membership blocks admission replay');
select throws_ok($$select pg_temp.roster()$$,'42501',null,'revoked membership blocks roster replay');
reset role;
update public.memberships set status='active' where id='d1500000-0000-4000-8000-000000000001';
update auth.sessions set not_after=now()-interval '1 second' where id='d1200000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select pg_temp.admit()$$,'42501',null,'expired session blocks admission replay');
select throws_ok($$select pg_temp.roster()$$,'42501',null,'expired session blocks roster replay');
reset role;
select is((select count(*)::integer from public.client_transitions),1,'all failures and replays leave one immutable admission');
select is((select count(*)::integer from private.care_roster_versions),1,'all failures and replays leave one immutable allocation');
select * from finish();
rollback;
